if [ "$T8" = rebooting ] && [ -s $P/itest-reboot-q2.boot_id.pre ]; then B0=$(cat $P/itest-reboot-q2.boot_id.pre); B1=; SEEN=; OUT=; RC=; n=0; while :; do OUT=$(timeout 20 ssh -n -o BatchMode=yes -o ConnectTimeout=10 egw-tcg cat /proc/sys/kernel/random/boot_id 2>"$P/itest-reboot-q2.ssh.err"); RC=$?; if [ "$RC" = 0 ]; then B1=$OUT; else B1=; fi; [ -z "$B1" ] || SEEN=$B1; if [ "$RC" = 0 ] && [[ $B1 =~ ^[0-9a-f-]{36}$ ]] && [ "$B1" != "$B0" ]; then break; fi; n=$((n + 1)); [ "$n" -lt 90 ] || break; sleep 10; done; if [ "$RC" = 0 ] && [[ $B1 =~ ^[0-9a-f-]{36}$ ]] && [ "$B1" != "$B0" ]; then echo "$B1" > $P/itest-reboot-q2.boot_id.post && [ -s $P/itest-reboot-q2.boot_id.post ] && echo "REBOOT SHOWN: boot id $B0 -> $B1 (read $((n + 1)) of at most 90, 10 s apart, each bounded to 20 s)" && T8=rebooted || stop "test 8: the new boot id $B1 was read but NOT saved to $P/itest-reboot-q2.boot_id.post - repeat this line"; elif [ -z "$SEEN" ]; then stop "test 8: reboot NOT shown - the guest never answered a boot id read that ended with exit status 0 in 90 reads 10 s apart (BatchMode, ConnectTimeout 10, each read ended by timeout after 20 s - a read that does not end with exit status 0, refused (255), failed or ended by the timeout (124), is no answer whatever it printed, and counts; the last read ended with exit $RC, printed '$OUT' and said: $(tail -n 1 "$P/itest-reboot-q2.ssh.err" 2>/dev/null)): still booting, down, sshd not up, or a refusal on the host side; look at the QEMU console of 3.3 before anything else - a QEMU process that has EXITED is a STOP here, not a re-launch: a re-launch (3.3, the same data disk) is an operator decision to record; repeat this line once the guest answers"; elif [ -z "$B1" ]; then stop "test 8: reboot NOT shown - the guest answered the old boot id $SEEN and then stopped answering (the last read ended with exit $RC and printed '$OUT': no answer, none within a read's 20 s, or an answer whose read did not end with exit status 0, which is no answer), and did not come back within 90 reads 10 s apart: look at the QEMU console of 3.3 (a QEMU process that has exited is a STOP here, not a re-launch; after a recorded re-launch a repeat would show persistence across a re-launch, not the in-process reboot, and in a battery this STOP is a halt); repeat this line once the guest answers"; elif [ "$B1" = "$B0" ]; then stop "test 8: reboot NOT shown - the guest kept answering the OLD boot id $B0 in 90 reads 10 s apart (last answer $B1): the reboot did not happen or has not started; repeat this line once it has, or record the finding"; else stop "test 8: reboot NOT shown - the guest's last answer is not a boot id ('$B1'; the kernel file holds 36 characters of 0-9, a-f and '-') after 90 reads 10 s apart: not that file's content (a banner, a shell message, a truncated read) - look at what the ssh prints and record the finding; repeat this line once the guest answers a boot id"; fi; else stop "test 8: the reboot was not issued by the line above (T8='$T8') or $P/itest-reboot-q2.boot_id.pre is missing or empty - nothing was read"; fi
